"""Publish the verified TypeScript code narration walkthrough with chapters and capture evidence."""
from pathlib import Path
import json,html,hashlib,shutil
R=Path(__file__).resolve().parents[1];N='managed-agents-typescript-walkthrough';P=R/'presentations'/N;V=R/'videos'/N
TITLE='TypeScript Walkthrough: Listen, Follow the Code, and Continue Each Explanation'
r=json.loads((V/'validation.json').read_text(encoding='utf-8'));assert r['fullVideoAndAudioDecode']=='passed';assert hashlib.sha256((V/r['file']).read_bytes()).hexdigest()==r['sha256']
t=json.loads((V/'timeline.json').read_text(encoding='utf-8'));story=json.loads((P/'storyboard.json').read_text(encoding='utf-8'));e=json.loads((V/'walkthrough-evidence.json').read_text(encoding='utf-8'))
assert len(t['slides'])==len(story)==18 and not e['errors'] and not e['liveExecution'] and not e['labRequests']
