(V/'index.html').write_text(page,encoding='utf-8');sec=int(r['durationSeconds']);stamp=f'{sec//60}:{sec%60:02}'
catalog=R/'videos/index.html';body=catalog.read_text(encoding='utf-8');card=f'<article data-project="{N}"><span>CLAUDE MANAGED AGENTS · TYPESCRIPT WALKTHROUGH</span><a href="{N}/index.html"><img loading="lazy" src="{N}/cover.png" alt="{html.escape(TITLE)}"></a><div><h2>{html.escape(TITLE)}</h2><p>Verified · {stamp} · 1080p · Yash narration · {len(e["shots"])} real application views</p><a href="{N}/{r["file"]}">MP4</a> · <a href="{N}/index.html">Player and chapters</a></div></article>'
